+import { isFalsy } from "@/utils/helpers";
+import { isNil } from "lodash";
+import moment from "moment";
+
+export const atualizarDataFim = (valoresAlterados, todosOsValores) => {
+  const mudouDataInicio = valoresAlterados?.dataInicio;
+  const mudouQuantidadeDias = valoresAlterados?.quantidadeDias;
+
+  if (isFalsy(mudouDataInicio) && isFalsy(mudouQuantidadeDias)) {
+    return;
+  }
+
+  if (isFalsy(todosOsValores)) {
+    return;
+  }
+
+  const dataInicio = todosOsValores?.dataInicio;
+  const quantidadeDias = todosOsValores?.quantidadeDias;
+
+  if (isNil(dataInicio) || isNil(quantidadeDias)) {
+    return;
+  }
+
+  const novaDataFim = moment(dataInicio).add(quantidadeDias - 1, "days");
+
+  return novaDataFim;
+};

