+/**
+ * Extrai a ordenação inicial a partir do parâmetro `sort` do filtro.
+ * Formato esperado: `["campo,ASC"]` ou `["campo,DESC"]`.
+ */
+export function extrairOrdenacaoDeFiltro(filtro = {}) {
+  const sort = isArray(filtro.sort) ? filtro.sort[0] : null;
+
+  if (!sort) {
+    return { campo: null, ordem: null };
+  }
+
+  const [campo, direcao] = sort.split(",");
+  return {
+    campo,
+    ordem: direcao === "DESC" ? "descend" : "ascend",
+  };
+}
+
+/**
+ * Monta o parâmetro `sort` para a API a partir da ordenação da tabela.
+ */
+export function montarParametroSort(campo, ordemAntd, filtroInicial = {}) {
+  if (!campo || !ordemAntd) {
+    return filtroInicial.sort;
+  }
+
+  const direcao = ordemAntd === "descend" ? "DESC" : "ASC";
+  return [`${campo},${direcao}`];
+}
