+import { DATA_FORMATO_ISO } from "@/pages/util/constUtils";
+import { processarRangeInicioFim } from "@/utils/momentUtils";
+import { isEqual, isNil, omitBy } from "lodash";
+import { FILTRO_TODOS } from "../constants/situacaoEstruturalRelatorio";
+
+export function prepararFiltrosHistoricoSituacaoEstrutural(filtros) {
+  const { periodo, situacaoEstrutura, ...resto } = filtros;
+
+  const filtroPeriodo = processarRangeInicioFim(periodo, {
+    campoInicio: "periodoInicio",
+    campoFim: "periodoFim",
+    formato: DATA_FORMATO_ISO,
+  });
+
+  const situacaoFiltrada = isEqual(situacaoEstrutura, FILTRO_TODOS) ? undefined : situacaoEstrutura;
+
+  return omitBy(
+    {
+      ...resto,
+      ...filtroPeriodo,
+      situacaoEstrutura: situacaoFiltrada,
+    },
+    (valor) => isNil(valor) || isEqual(valor, "")
+  );
+}

